// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { searchProducts } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const errors: string[] = [];
    page.on('pageerror', (err) => errors.push(err.message));

    await page.goto(baseUrl);
    await searchProducts(page, "cotton");

    await expect(page).toHaveURL(`${baseUrl}/search?q=cotton`);
    await expect(page.getByRole("textbox", { name: "Search products..." })).toHaveValue("cotton");

    // The PR specifies a case-insensitive substring match on product NAME. "cotton" appears in
    // no product name (only in the Tank Top description), so the no-results state is expected.
    // This FAILS today because SearchProducts also matches Description (product_catalog.go:66).
    await expect(page.locator(".hot-product-card")).toHaveCount(0);
    await expect(page.getByText("No products found for")).toBeVisible();

    expect(errors).toHaveLength(0);
});
